  ],
  "claims": [
    {
      "claim": "The query is a triptan (3-(2-dimethylaminoethyl)indole with a 5-(pyrrolidin-1-ylsulfonylmethyl) substituent); L6 retrieves hepatic-clearance records for close triptan analogs rizatriptan and eletriptan.",
      "card_ids": ["C227","C243"]
    },
    {
      "claim": "Rizatriptan, a close triptan analog, has moderate human liver microsomal intrinsic clearance (~11–12 µL/min/mg) that is MAO-mediated (pargyline-sensitive, minimal NADPH effect), not an extreme first-pass clearance.",
      "card_ids": ["C227","C242"]
    },
    {
      "claim": "Eletriptan, a triptan with a sulfonyl-containing 5-substituent, has low-to-moderate HLM intrinsic clearance (3.02–4.34 µL/min/mg) and CYP-mediated metabolism without MAO involvement.",
      "card_ids": ["C243","C247","C223"]
    },
    {
      "claim": "5-MeO-DMT, a less transferable tryptamine lacking the 5-sulfonylmethyl substituent, shows high hepatocyte intrinsic clearance (81.9–92.1 µL/min/10^6 cells), but this does not transfer to the query because of the different 5-substituent and metabolic context.",
      "card_ids": ["C201","C209"]
    },
    {
      "claim": "L1 gold contexts are predominantly high absolute F measurements (bepridil 59–62%, vilazodone 72%, flavoxate ~100%, sulthiame complete, 5-HTP 49%); the only low-F context (ilomastat) is structurally unrelated.",
      "card_ids": ["C01","C03","C16","C19","C20","C11"]
    },
    {
      "claim": "L3/L4/L5 records for triptans and basic amines show measurable oral systemic exposure, high aqueous solubility across GI pH, high absorptive Caco-2/intestinal permeability, and only modest non-saturating efflux.",
      "card_ids": ["C66","C80","C93","C105","C132","C118","C165","C181","C160","C190","C185","C192","C188"]
    },
    {
      "claim": "No transferable threshold-relevant evidence supports F < 20% for the query; unresolved uncertainty is expressed through confidence and gaps, not as a low prediction.",
      "card_ids": ["C11"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C227","C242","C243","C247","C223"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for almotriptan is present in any card.",
    "No matched oral-versus-IV AUC/Cmax comparison is available for the query.",
    "No query-specific hepatic clearance or metabolic stability measurement exists; L6 values come from analogs (rizatriptan, eletriptan, 5-MeO-DMT, imipramine, etc.).",
    "L6 records are mechanistic and not direct F endpoints; species/assay differences (HLM, hepatocytes, rat/mouse) limit quantitative transfer.",
    "High-clearance 5-MeO-DMT records (C201, C209) have low transferability due to the different 5-substituent and metabolic context.",
    "Food effect and formulation dependence for the query are unknown."
  ],
  "decision_summary": "Predicted high (F >= 20%). L1 gold contexts are predominantly high absolute F; L3-L5 show oral exposure, high solubility, and high absorptive permeability for close triptan analogs and basic amines; L6 adds hepatic-clearance records showing moderate, not extreme, HLM intrinsic clearance for rizatriptan and eletriptan, reducing first-pass concern. High-clearance 5-MeO-DMT records are not transferable due to structural differences. No threshold-relevant low-F evidence transfers to the query; confidence remains moderate because no direct query-specific F measurement exists."
}

